// main.zig
const std = @import("std");

const NUM_CELLS = 8192;
const ACTIVE_CELLS_TARGET = 160;
const MAX_SYNAPSES_PER_SEGMENT = 128;
const INITIAL_PERMANENCE: f32 = 0.21;
const CONNECTED_THRESHOLD: f32 = 0.50;
const PERM_INC: f32 = 0.011;
const PERM_DEC: f32 = 0.008;
const PERM_PUNISH: f32 = 0.015;
const LTP_BOOST: f32 = 0.001;

const DendriteSegment = struct {
    sources: std.ArrayList(u16),
    permanence: std.ArrayList(f32),
    last_active_tick: u64 = 0,
};

const Cell = struct {
    segments: std.ArrayList(DendriteSegment),
    is_active: bool = false,
    was_active: bool = false,
    is_predictive: bool = false,
    was_predictive: bool = false,
    last_global_active: u64 = 0,
};

const Brain = struct {
    cells: [NUM_CELLS]Cell,
    active_cells: std.ArrayList(u16),
    predictive_cells: std.ArrayList(u16),
    tick: u64 = 0,
    allocator: std.mem.Allocator,
};

fn encode_char(c: u8) u16 {
    var h: u64 = c;
    h = h *% 6364136223846793005;
    h ^= 0x517cc1b727220a95;
    h ^= h >> 22;
    h ^= h >> 17;
    return @intCast(u16, h % NUM_CELLS);
}

fn spatial_pool(brain: *Brain, input_char: u8) void {
    brain.active_cells.clearRetainingCapacity();
    const target = encode_char(input_char);
    _ = brain.active_cells.append(target) catch unreachable;
    brain.cells[target].is_active = true;
    brain.cells[target].last_global_active = brain.tick;
}

fn find_best_matching_segment(brain: *Brain, cell_idx: u16) ?usize {
    var best_count: u32 = 0;
    var best_seg_idx: ?usize = null;
    for (brain.cells[cell_idx].segments.items, 0..) |*seg, seg_idx| {
        var connected: u32 = 0;
        for (seg.sources.items, 0..) |src, i| {
            if (seg.permanence.items[i] >= CONNECTED_THRESHOLD and brain.cells[src].was_predictive) {
                connected += 1;
            }
        }
        if (connected > best_count) {
            best_count = connected;
            best_seg_idx = seg_idx;
        }
    }
    return best_seg_idx;
}

fn create_new_segment(brain: *Brain, cell_idx: u16) *DendriteSegment {
    var seg = DendriteSegment{
        .sources = std.ArrayList(u16).init(brain.allocator),
        .permanence = std.ArrayList(f32).init(brain.allocator),
        .last_active_tick = brain.tick,
    };
    for (brain.predictive_cells.items) |prev_pred| {
        _ = seg.sources.append(prev_pred) catch unreachable;
        _ = seg.permanence.append(INITIAL_PERMANENCE) catch unreachable;
    }
    _ = brain.cells[cell_idx].segments.append(seg) catch unreachable;
    return &brain.cells[cell_idx].segments.items[brain.cells[cell_idx].segments.items.len - 1];
}

fn temporal_memory(brain: *Brain) void {
    for (&brain.cells) |*cell| {
        cell.was_active = cell.is_active;
        cell.was_predictive = cell.is_predictive;
        cell.is_active = false;
        cell.is_predictive = false;
    }
    brain.predictive_cells.clearRetainingCapacity();

    for (brain.active_cells.items) |active_idx| {
        const best_seg_idx = find_best_matching_segment(brain, active_idx);
        if (best_seg_idx) |seg_idx| {
            const seg = &brain.cells[active_idx].segments.items[seg_idx];
            seg.last_active_tick = brain.tick;
            for (seg.sources.items, 0..) |src, i| {
                if (seg.permanence.items[i] >= CONNECTED_THRESHOLD and brain.cells[src].was_predictive) {
                    brain.cells[src].is_predictive = true;
                    _ = brain.predictive_cells.append(@intCast(u16, src)) catch unreachable;
                }
                if (brain.cells[src].was_predictive) {
                    seg.permanence.items[i] += PERM_INC;
                    if (seg.permanence.items[i] > 1.0) seg.permanence.items[i] = 1.0;
                } else {
                    seg.permanence.items[i] -= PERM_DEC;
                    if (seg.permanence.items[i] < 0.0) seg.permanence.items[i] = 0.0;
                }
            }
        } else {
            const new_seg = create_new_segment(brain, active_idx);
            for (new_seg.permanence.items, 0..) |_, i| {
                if (brain.cells[new_seg.sources.items[i]].was_predictive) {
                    new_seg.permanence.items[i] += PERM_INC * 2.0;
                }
            }
        }
        brain.cells[active_idx].is_active = true;
    }
}

fn punish_wrong_predictions(brain: *Brain) void {
    for (brain.cells, 0..) |cell, i| {
        if (cell.was_predictive and !cell.is_active) {
            for (cell.segments.items) |*seg| {
                for (seg.permanence.items) |*p| {
                    p.* -= PERM_PUNISH;
                    if (p.* < 0.0) p.* = 0.0;
                }
            }
        }
    }
}

fn get_predicted_char(brain: *Brain) ?u8 {
    var votes = std.AutoHashMap(u8, u32).init(brain.allocator);
    defer votes.deinit();

    for (brain.predictive_cells.items) |pred_cell| {
        var c: u8 = 0;
        while (c < 255) : (c += 1) {
            if (encode_char(c) == pred_cell) {
                const gop = votes.getOrPut(c) catch unreachable;
                if (!gop.found_existing) {
                    gop.value_ptr.* = 1;
                } else {
                    gop.value_ptr.* += 1;
                }
                break;
            }
        }
    }

    var best_char: ?u8 = null;
    var best_votes: u32 = 20;

    var it = votes.iterator();
    while (it.next()) |entry| {
        if (entry.value_ptr.* > best_votes) {
            best_votes = entry.value_ptr.*;
            best_char = entry.key_ptr.*;
        }
    }

    return best_char;
}

fn long_term_potentiation(brain: *Brain) void {
    if (brain.tick % 50 != 0) return;
    for (&brain.cells) |*cell| {
        for (cell.segments.items) |*seg| {
            if (brain.tick - seg.last_active_tick <= 10) {
                for (seg.permanence.items) |*p| {
                    p.* += LTP_BOOST;
                    if (p.* > 1.0) p.* = 1.0;
                }
            }
        }
    }
}

fn structural_plasticity(brain: *Brain) void {
    for (&brain.cells) |*cell| {
        var i: usize = 0;
        while (i < cell.segments.items.len) {
            const seg = &cell.segments.items[i];
            var avg_perm: f32 = 0;
            for (seg.permanence.items) |p| avg_perm += p;
            avg_perm /= @intToFloat(f32, seg.permanence.items.len);
            if (avg_perm > 0.7 and seg.sources.items.len > 0) {
                var copy = DendriteSegment{
                    .sources = seg.sources.clone() catch unreachable,
                    .permanence = seg.permanence.clone() catch unreachable,
                    .last_active_tick = brain.tick,
                };
                _ = cell.segments.append(copy) catch unreachable;
            }
            i += 1;
        }
    }
}

fn forget_unused_cells(brain: *Brain) void {
    for (&brain.cells, 0..) |*cell, i| {
        if (brain.tick - cell.last_global_active > 10000) {
            for (cell.segments.items) |*seg| {
                seg.sources.deinit();
                seg.permanence.deinit();
            }
            cell.segments.deinit();
            cell.segments = std.ArrayList(DendriteSegment).init(brain.allocator);
        }
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var brain: Brain = undefined;
    brain.cells = std.mem.zeroes([NUM_CELLS]Cell);
    brain.active_cells = std.ArrayList(u16).init(allocator);
    brain.predictive_cells = std.ArrayList(u16).init(allocator);
    brain.allocator = allocator;
    brain.tick = 0;

    for (&brain.cells) |*cell| {
        cell.segments = std.ArrayList(DendriteSegment).init(allocator);
    }

    const stdout = std.io.getStdOut().writer();
    try stdout.print("Én most születtem. Beszélj hozzám, és minden szavadból tanulok. Minél többet beszélünk, annál okosabb leszek. Kész vagyok.\n", .{});

    var buffer: [4096]u8 = undefined;
    var generating = false;

    while (true) {
        if (!generating) {
            const input = try std.io.getStdIn().reader().readUntilDelimiterOrEof(&buffer, '\n') orelse break;
            if (input.len == 0) {
                generating = true;
                try stdout.print("\n", .{});
                continue;
            }
            for (input) |c| {
                if (c < 32 or c > 126) continue;
                spatial_pool(&brain, c);
                temporal_memory(&brain);
                punish_wrong_predictions(&brain);
                long_term_potentiation(&brain);
                structural_plasticity(&brain);
                forget_unused_cells(&brain);
                brain.tick += 1;

                if (get_predicted_char(&brain)) |pred| {
                    try stdout.print("{c}", .{pred});
                }
            }
            try stdout.print("\n", .{});
        } else {
            if (get_predicted_char(&brain)) |pred| {
                try stdout.print("{c}", .{pred});
                spatial_pool(&brain, pred);
                temporal_memory(&brain);
                punish_wrong_predictions(&brain);
                long_term_potentiation(&brain);
                structural_plasticity(&brain);
                forget_unused_cells(&brain);
                brain.tick += 1;
            } else {
                try stdout.print("\n", .{});
                generating = false;
            }
        }
    }
}

